import unittest
from candidate import longest
import random
import string


class TestLongestFunction(unittest.TestCase):
    def test_longest_single_element(self):
        self.assertEqual(longest(['hello']), 'hello')

    def test_longest_single_empty_string(self):
        self.assertEqual(longest(['']), '')

    def test_longest_multiple_different_lengths(self):
        self.assertEqual(longest(['a', 'abc', 'ab']), 'abc')

    def test_longest_multiple_same_length(self):
        self.assertEqual(longest(['abc', 'def', 'ghi', 'ab']), 'abc')

    def test_longest_all_same_length(self):
        self.assertEqual(longest(['a', 'b', 'c']), 'a')

    def test_longest_empty_list(self):
        self.assertIsNone(longest([]))

    def test_longest_none_input(self):
        with self.assertRaises(TypeError):
            longest(None)

    def test_longest_non_iterable_input(self):
        with self.assertRaises(TypeError):
            longest(123)

    def test_longest_list_with_non_string(self):
        with self.assertRaises(TypeError):
            longest(['abc', 123, 'def'])

    def test_longest_with_unicode(self):
        unicode_str = '𝔘𝔫𝔦𝔠𝔬𝔡𝔢'
        self.assertEqual(longest(['short', unicode_str, 'medium']), unicode_str)

    def test_longest_with_whitespace(self):
        self.assertEqual(longest(['  ', '    ', '   ']), '    ')

    def test_longest_list_of_only_empty_strings(self):
        self.assertEqual(longest(['', '', '']), '')

    def test_longest_large_input(self):
        pool = [''.join(random.choices(string.ascii_lowercase, k=random.randint(1, 1000)))
                for _ in range(1000)]
        longest_str = max(pool, key=len)
        self.assertEqual(longest(pool), longest_str)

    def test_return_type(self):
        result = longest(['a', 'ab'])
        self.assertTrue(isinstance(result, (str, type(None))))

    def test_longest_tuple_input(self):
        self.assertEqual(longest(('x', 'xy', 'xyz')), 'xyz')

    def test_longest_first_longest(self):
        self.assertEqual(longest(['ab', 'cd', 'ef', 'abc', 'abcd', 'abcdx']), 'abcdx')

    def test_longest_first_longest_with_multiple_max(self):
        self.assertEqual(longest(['ab', 'abcd', 'abcd', 'abc']), 'abcd')

    def test_longest_includes_numbers_as_characters(self):
        self.assertEqual(longest(['a1', 'abc', 'ab2c']), 'ab2c')

    def test_longest_with_non_ascii_characters(self):
        self.assertEqual(longest(['héllo', 'world', 'café']), 'héllo')

    def test_longest_with_empty_and_non_empty(self):
        self.assertEqual(longest(['', 'nonempty']), 'nonempty')


if __name__ == '__main__':
    unittest.main()
